UPDATE "Place" p SET "website" = 'https://capellahotels.com/en/capella-hanoi' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'hanoi' AND p.slug = 'capella-hanoi';
UPDATE "Place" p SET "area" = 'Nam Tu Liem', "blurb" = 'National museum of Vietnam''s military history, moved in November 2024 to a large new site on Thang Long Boulevard.' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'hanoi' AND p.slug = 'vietnam-military-history-museum';
