UPDATE "Item" SET "priceCents" = 38, "priceNote" = '₫10,000–15,000 a glass of bia hoi', "priceSourceUrl" = 'https://jackfruitadventure.com/beer-street-hanoi/', "priceCheckedAt" = '2026-10-25' WHERE "id" = 'hanoi-3-days-thebrokebackpacker--ta-hien-beer-street' AND "priceCents" IS NULL;
